INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES
(37211, 0, 0, 0, 0, 'An anonymous collector of valuable fossils and antiques has offered the preservation society a huge cash reward for Bergruu''s horn.$b$bA huge reward, $n... HUGE!', 0),
(37221, 0, 0, 0, 0, 'Few elekk have lived as long as Dekorhan. Elekk tusks continue to grow throughout the elekk''s lifetime.$b$bThis makes Dekorhan''s tusks some of the largest and oldest on Draenor.$b$bDo you hear what I hear, $n? That''s the sound of all the gold jingling in our pockets after you bring me Dekorhan''s tusk!', 0),
(37222, 0, 0, 0, 0, 'Most talbuk are peaceful creatures that will only attack when they are defending their herd. Not Direhoof though, that talbuk is one of the most aggresively dangerous beasts I''ve ever encountered... and one of the most magnificent talbuk I''ve ever seen!$b$bIf you encounter Direhoof while adventuring and live to tell the tale, return to me with the beast''s hide and I''ll see that you''re rewarded!', 0),
(37223, 0, 0, 0, 0, 'Deep in the forest of northern Nagrand is a giant Gronn known as Gagrog the Brutal. In case you''re wondering, he didn''t get his name by giving out free hugs... this Gronn is as savage and murderous as they come!$b$bNow look, I''m not telling you to go try and hunt this thing down... that would be suicide... but if by some miracle you fight Gagrog and live, make sure you bring back his skull!', 0),
(37224, 0, 0, 0, 0, 'Not far from here is a hippo of unusual size and ferocity known as Mu''gra. I''ve been contacted by a private collector that would like to acquire Mu''gra''s teeth for a special exhibit.$b$bHippo teeth are extremely difficult to extract, and we can''t be selling damaged goods so just bring back the entire head, got it?$b$bGood luck!', 0),
(37225, 0, 0, 0, 0, 'Windrocs can be found all over Nagrand, from the highest peaks to the lowest valleys. However, one windroc in particular is extremely elusive and is rarely sighted, it is known to the orcs as Thek''talon.$b$bIf I know anything, it''s that people will pay a lot of money for anything that is rare or elusive!', 0),
(37226, 0, 0, 0, 0, 'Xelganak is as deadly as they come, $n! I don''t recommend going after Xelganak unless you love money, adventure, and glory.$b$bXelganak''s poison stinger would be an easy sell to the right collector, so if you''re up for the challenge I''ll make sure you get handsomely rewarded.$b$bJust don''t go getting your face melted off like Bozzil, ok?', 0),
(37520, 0, 0, 0, 0, 'Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you''ll ever encounter, she is also a savagely beautiful creature.$b$bVileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I''ll make sure you get a cut of the profit!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(37210, 'frFR', 'Aogexon est l’un des bestiaux les plus redoutés de Nagrand ; un traqueur sylvestre d’une taille et d’une férocité peu communes !$b$bJ’ai déjà reçu des offres émanant de collectionneurs qui donneraient gros pour mettre la main sur l’un des crocs acérés d’Aogexon. Si vous voulez relever le défi, vous avez une chance de trouver cette créature dans le marais situé non loin d’ici où on le voit parfois rôder.$b$bBonne chance !', 0),
(37211, 'frFR', 'Un collectionneur anonyme d’antiquités et de fossiles rares a proposé à la Société de Conservation une énorme récompense en échange de la corne de Bergruu.$b$bEt quand je dis énorme, $n… c’est ÉNORME !', 0),
(37221, 'frFR', 'Peu d’elekk ont l’occasion d’atteindre l’âge canonique de Dekorhan, et il se trouve que les défenses de ces créatures poussent tout au long de leur vie.$b$bDu coup, celles de Dekorhan font partie des plus anciennes et donc des plus grandes qu’on puisse trouver en Draenor.$b$bVous entendez le même tintement que moi, $n ? C’est celui des pièces d’or qui vont atterrir dans nos poches une fois que vous m’aurez apporté une défense de Dekorhan !', 0),
(37222, 'frFR', 'Les talbuks sont pour la plupart des créatures dociles qui n’attaquent généralement que pour défendre leurs troupeaux, mais Sabot-Sinistre n’est pas de ceux-là. C’est l’une des bêtes sauvages les plus agressives et les plus dangereuses que j’aie pu croiser… et sans doute le plus magnifique spécimen de talbuk qu’il m’ait été donné de voir !$b$bSi jamais vous tombez sur Sabot-Sinistre et que vous survivez à cette rencontre, rapportez-moi sa peau et je veillerai à ce que vous soyez récompensé comme il se doit !', 0),
(37223, 'frFR', 'Un Gronn géant du nom de Gagrog le Brutal rôde dans la forêt du nord de Nagrand. Au cas où vous vous poseriez la question, il n’a pas obtenu son surnom en distribuant des friandises aux passants… Ce gronn est aussi sauvage et assoiffé de sang qu’on est en droit de l’attendre !$b$bJe ne vous demande pas d’aller traquer cette créature… ce serait du suicide… mais si jamais vous êtes un jour amené à combattre Gagrog et que vous survivez à cette rencontre, pensez à me rapporter son crâne !', 0),
(37224, 'frFR', 'Non loin d’ici se trouve le territoire d’une femelle hippopotame nommée Mu’gra dont la taille exceptionnelle n’a d’égale que la férocité. J’ai reçu une offre émanant d’un collectionneur qui voudrait faire l’acquisition des dents de cet animal, dans le cadre d’une exposition spéciale.$b$bLes dents d’hippopotame sont particulièrement difficiles à extraire, et nous ne pouvons nous permettre de présenter aux clients des articles endommagés, alors tâchez de nous rapporter la tête entière, entendu ?$b$bBonne chance !', 0),
(37225, 'frFR', 'Des venterocs, on en trouve partout en Nagrand, que ce soit au sommet de ses plus hauts pics ou au fin fond de ses vallées les plus encaissées. Toutefois, l’un d’entre eux s’est révélé particulièrement insaisissable et ne se montre que rarement. Les Orcs le connaissent sous le nom de Thek’serre.$b$bEt ce que je sais, c’est que pour certaines personnes, ce genre de rareté vaut de l’or, beaucoup d’or !', 0),
(37226, 'frFR', 'Xelganak est une créature tout ce qu’il y a de plus meurtrière, $n ! Je vous déconseille de vous mettre en tête de la traquer, à moins que vous n’ayez développé un goût particulier pour l’argent, l’aventure et la renommée.$b$bTout collectionneur qui se respecte n’hésitera pas à payer le prix fort pour se procurer le dard de Xelganak, et si vous relevez le défi, je veillerai à ce que vous touchiez une récompense pour le moins coquette.$b$bÉvitez juste de vous faire refaire le portrait comme Bozzil, d’accord ?', 0),
(37520, 'frFR', 'Vilegriffe est une prédatrice vicieuse crainte dans tout Nagrand. Bien qu’elle soit le raptor le plus dangereux jamais connu, elle est aussi considérée comme une créature à la beauté sauvage.$b$bVilegriffe doit être préservée pour les futures générations ! Si vous réussissez à me rapporter l’une de ses griffes vicieuses, je vous donnerai une partie des bénéfices !', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES
(35147, 0, 0, 0, 0, 'What these ogres see as junk, we see as money!', 0),
(37125, 0, 0, 0, 0, 'Every once in a while an archaeologist experiences a rare find... an artifact that time has delicately preserved through the ages, as if it had simply fallen out of a time machine.$b$bEven thinking about the thrill of such a find makes me get all emotional... relics like that are worth a freakin'' fortune!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `Locale`, `CompletionText`, `VerifiedBuild`) VALUES
(35147, 'frFR', 'Là où ces Ogres ne voient que des déchets, nous flairons le bon argent !', 0),
(37125, 'frFR', 'De temps à autre, un archéologue découvre un objet rare… un artéfact épargné par les outrages du temps, comme sorti d’une machine temporelle.$b$bLe simple fait de penser à une découverte pareille m’émeut profondément… De telles reliques valent une sacrée fortune !', 0);
